-- Platform Unified Hierarchical Record Registry v2.0
begin;

alter table public.platform_record_types
  add column if not exists route_url text,
  add column if not exists owner_role text,
  add column if not exists owner_section text,
  add column if not exists record_group_key text,
  add column if not exists record_group_name text,
  add column if not exists is_assignable boolean not null default true,
  add column if not exists supports_files boolean not null default true,
  add column if not exists supports_approval boolean not null default true,
  add column if not exists supports_analysis boolean not null default true,
  add column if not exists configuration_json jsonb not null default '{}'::jsonb,
  add column if not exists is_active boolean not null default true;

