on conflict (module_key,record_type) do update
set display_name=excluded.display_name,
    route_url=excluded.route_url,
    owner_role=excluded.owner_role,
    owner_section=excluded.owner_section,
    record_group_key=excluded.record_group_key,
    record_group_name=excluded.record_group_name,
    is_assignable=excluded.is_assignable,
    supports_files=excluded.supports_files,
    supports_approval=excluded.supports_approval,
    supports_analysis=excluded.supports_analysis,
    is_active=excluded.is_active,
    configuration_json=excluded.configuration_json;

-- فهارس تسريع اختيار السجلات في مركز التكليفات
create index if not exists idx_platform_record_types_owner_section
on public.platform_record_types(owner_role,owner_section);

create index if not exists idx_platform_record_types_record_group
on public.platform_record_types(module_key,record_group_key);

commit;

-- تحقق اختياري
select owner_role, owner_section, record_group_name, count(*) as records_count
from public.platform_record_types
where is_active=true
group by owner_role, owner_section, record_group_name
order by owner_role, owner_section, record_group_name;
